bool em2::TestNativeFullMaterialLighting(rex::ui::d3d12::D3D12Provider& provider,const std::filesystem::path& output){
    return TestWorldSurfaceCapture(provider,output/"world-combined",true) && TestWorldSurfaceCapture(provider,output/"world-combined-dual",true,true) && TestWorldSurfaceCapture(provider,output/"world-surface") && TestWorldMaterialLighting(provider,output/"world-base-dual",true,true) && TestWorldMaterialLighting(provider,output/"world-base",false,true) && TestWorldMaterialLighting(provider,output/"world-baked-dual",true) && TestWorldMaterialLighting(provider,output/"world-baked") && TestMaterialAmbientClear(provider,output/"generic-clear") && TestFullMaterialLighting(provider,output/"dual",em2::material_shader_data::full_difference)
        && TestFullMaterialLighting(provider,output/"suffix",em2::material_shader_data::full_suffix_difference)
        && TestFullMaterialLighting(provider,output/"private-export",em2::material_shader_data::full_suffix_difference,true)
        && TestFullMaterialLighting(provider,output/"private-fp16-hdr",em2::material_shader_data::full_suffix_difference,true,true)
        && TestFullMaterialLighting(provider,output/"original-pair-fp16-hdr",em2::material_shader_data::full_suffix_difference,true,true,true)
        && TestFullMaterialLighting(provider,output/"original-pair-linear-hdr",em2::material_shader_data::full_suffix_difference,true,true,true,true)
        && TestFullMaterialLighting(provider,output/"mickey-full-linear-hdr",em2::material_shader_data::full_suffix_difference,true,true,false,true,true);
}
